#include "cppunivariate/distributions/bhatt/mle.hpp"
#include "json_loader.hpp"
#include <iostream>
#include <chrono>
#include <iomanip>
int main(){std::cout<<std::setprecision(17);const auto g=mltest::load_golden("univariateML-cpp/include/cppunivariate/distributions/bhatt/golden.json");std::vector<double> y;auto lo=*std::min_element(g.data.begin(),g.data.end()),hi=*std::max_element(g.data.begin(),g.data.end());double center=lo/2+hi/2,scale=hi/2-lo/2;for(double v:g.data)y.push_back((v-center)/scale);cppunivariate::bhatt_detail::WidthCertificate c({y.data(),y.size()},1e-10,500,NAN,NAN,center,scale);auto start=std::chrono::steady_clock::now();auto f=c.run();std::cout<<"status "<<int(f.status)<<" work "<<c.work.used<<" profiles "<<c.cache.size()<<" winners "<<c.winners.size()<<" seconds "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;for(const auto& w:c.winners){std::cout<<"winner "<<w.lo<<" "<<w.hi<<" error "<<w.root.error<<" accurate "<<w.root.accurate<<std::endl; auto coef=c.model.coefficients(w.root.enclosure);for(int i=0;i<3;++i){coef[i]=cppunivariate::bhatt_detail::CertInterval(scale)*coef[i];if(i==0)coef[i]=cppunivariate::bhatt_detail::CertInterval(center)+coef[i];std::cout<<"coefficient "<<i<<" lower "<<coef[i].lo<<" upper "<<coef[i].hi<<std::endl;}}std::cout<<"normal upper "<<c.normal_upper<<" uniform upper "<<c.uniform.loglik_upper<<" winner lower "<<c.incumbent<<std::endl;}
